mapper.select:
SELECT * FROM product_inventory WHERE 1=1

    AND product_id = #{productId}


    AND quantity >= #{minQuantity}


    AND quantity <= #{maxQuantity}


    AND reserved_quantity >= #{minReservedQuantity}


    AND reserved_quantity <= #{maxReservedQuantity}


    AND created_at >= #{startTime}


    AND created_at <= #{endTime}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM product_inventory WHERE 1=1

    AND product_id = #{productId}


    AND quantity >= #{minQuantity}


    AND quantity <= #{maxQuantity}


    AND reserved_quantity >= #{minReservedQuantity}


    AND reserved_quantity <= #{maxReservedQuantity}


    AND created_at >= #{startTime}


    AND created_at <= #{endTime}

mapper.update:
UPDATE product_inventory

    product_id = #{productId},
    quantity = #{quantity},
    reserved_quantity = #{reservedQuantity},
    updated_at = #{updatedAt}

WHERE id = #{id}

mapper.select:
SELECT pi.*, p.name as product_name, p.sku as product_sku
FROM product_inventory pi
INNER JOIN products p ON pi.product_id = p.id
WHERE pi.quantity <= #{threshold}
ORDER BY pi.quantity ASC
LIMIT #{offset}, #{limit}

SELECT pi.*, p.name as product_name, p.sku as product_sku
FROM product_inventory pi
INNER JOIN products p ON pi.product_id = p.id
WHERE pi.quantity >= #{threshold}
ORDER BY pi.quantity DESC
LIMIT #{offset}, #{limit}

